import {cardById,VERSION} from './content.js';
import {clone,random,hash} from './engine.js';
export function createArena(config){const squad=config.deck.slice(0,3).map(id=>{const c=cardById(id),level=config.levels[id]||1;return{id,name:c.name,color:c.color,hp:850+(level-1)*50,maxHp:850+(level-1)*50,attack:150+(level-1)*12,energy:0,guard:false}});return{version:VERSION,config:clone(config),rng:config.seed>>>0||1,round:1,active:0,squad,enemies:[{name:'Crimson challenger',hp:1000,maxHp:1000},{name:'Azure challenger',hp:1050,maxHp:1050},{name:'Gold challenger',hp:950,maxHp:950}],events:[],commands:[],result:null}}
export function arenaCommand(s,action,target=0){if(s.result)return{ok:false,error:'This Arena battle has ended.'};const f=s.squad[s.active];if(!['strike','guard','special'].includes(action))return{ok:false,error:'Unknown command'};if(action!=='guard'&&(!s.enemies[target]||s.enemies[target].hp<=0))return{ok:false,error:'Select a standing opponent.'};if(action==='special'&&f.energy<2)return{ok:false,error:'Build two energy with Strike or Guard.'};s.commands.push({action,target});
 if(action==='guard'){f.guard=true;f.energy=Math.min(3,f.energy+1);f.hp=Math.min(f.maxHp,f.hp+100);s.events.push(`${f.name} guards and recovers`)}else{const damage=f.attack*(action==='special'?3:1)+random(s,45);if(action==='special')f.energy-=2;else f.energy=Math.min(3,f.energy+1);s.enemies[target].hp=Math.max(0,s.enemies[target].hp-damage);s.events.push(`${f.name} ${action} · ${damage}`)}
 if(s.enemies.every(e=>!e.hp)){s.result='victory';return{ok:true}}
 let next=s.active+1;while(next<s.squad.length&&s.squad[next].hp<=0)next++;
 if(next<s.squad.length)s.active=next;else{for(const enemy of s.enemies.filter(e=>e.hp>0)){const alive=s.squad.filter(f=>f.hp>0);if(!alive.length)break;const f=alive[random(s,alive.length)],damage=Math.floor((130+random(s,50))*(f.guard?.4:1));f.hp=Math.max(0,f.hp-damage);s.events.push(`${enemy.name} counters ${f.name} · ${damage}`)}for(const f of s.squad)f.guard=false;s.round++;s.active=s.squad.findIndex(f=>f.hp>0);if(s.active<0)s.result='defeat'}return{ok:true}}
export function arenaReplay(record){const s=createArena(record.config);for(const c of record.commands){const r=arenaCommand(s,c.action,c.target);if(!r.ok)throw Error(r.error)}if(hash(s)!==record.stateHash)throw Error('Arena replay differs');return s}
